  "entspiegelt": "com tratamento antirreflexo",
  "kurzsichtig": "míope",
  "weitsichtig": "hipermetrope",
  "die Dioptrie": "a dioptria",
  "das Brillenetui": "o estojo dos óculos",
  "das Gestell": "a armação dos óculos",
  "der Bügel": "a haste",
